import torch,math; exec("class Solution:\n    def xavier_init(self, fi, fo):\n        torch.manual_seed(0)\n        std = math.sqrt(2.0/(fi+fo))\n        weights = torch.randn(fo, fi) * std\n        return torch.round(weights, decimals=4).tolist()\n    def kaiming_init(self, fi, fo):\n        torch.manual_seed(0)\n        std = math.sqrt(2.0/fi)\n        weights = torch.randn(fo, fi) * std\n        return torch.round(weights, decimals=4).tolist()\n    def check_activations(self, n, d, hd, it):\n        torch.manual_seed(0)\n        dims = [d] + [hd]*n\n        weights = []\n        for i in range(n):\n            std = math.sqrt(2.0/(dims[i]+dims[i+1])) if it=='xavier' else math.sqrt(2.0/dims[i]) if it=='kaiming' else 1.0\n            w = torch.randn(dims[i+1], dims[i]) * std\n            weights.append(w)\n        x = torch.randn(1, d)\n        stds = []\n        for w in weights:\n            x = torch.relu(x @ w.T)\n            stds.append(round(x.std().item(), 2))\n        return stds")